SELECT TO_CHAR(MBC.DTLANC, 'DD/MM/YYYY') AS DIA, NVL(CTA.CODCTABCOINT, 0) AS CODIGO, NVL(CTA.DESCRICAO, 'Outros/Não Identificado') AS NOME_CONTA, SUM((NVL(MBC.VLRLANC,0) * NVL(MBC.RECDESP,0))) AS OUTRAS_MOVIMENTACOES FROM TGFMBC MBC LEFT JOIN TSICTA CTA ON CTA.CODCTABCOINT = MBC.CODCTABCOINT WHERE EXISTS (SELECT 1 FROM TGFFIN FIN WHERE FIN.NUBCO = MBC.NUBCO AND FIN.PROVISAO = 'N') AND TRUNC(MBC.DTLANC) >= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(MBC.DTLANC) <= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15)) AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(MBC.CODCTABCOINT) || ',') > 0) GROUP BY TO_CHAR(MBC.DTLANC, 'DD/MM/YYYY'), CTA.CODCTABCOINT, CTA.DESCRICAO
